// Kaotic Chainz app kit: generated copy. Edit in app-portfolio/kit, then run scripts/sync-kit.sh.
//
// The app icon follows the theme. Each app ships one icon per theme (named after the theme id,
// generated by scripts/make-theme-icons.py) through the expo-alternate-app-icons config plugin.
// Until a build includes that native module, this quietly does nothing, so web, Expo Go and
// tests are unaffected.
import { requireOptionalNativeModule } from 'expo';

type IconModule = {
  setAlternateAppIcon: (name: string | null) => Promise<string | null>;
  getAppIconName?: () => string | null;
  supportsAlternateIcons?: boolean;
};

let mod: IconModule | null = null;
try {
  mod = requireOptionalNativeModule<IconModule>('ExpoAlternateAppIcons');
} catch {
  mod = null;
}

export const appIconSupported = !!mod && mod.supportsAlternateIcons !== false;

/** The icon name for a theme: null means the app's main icon (its default theme). */
export function iconNameFor(themeId: string, defaultTheme: string): string | null {
  return themeId === defaultTheme ? null : themeId;
}

export async function applyAppIcon(themeId: string, defaultTheme: string): Promise<boolean> {
  if (!mod || !appIconSupported) return false;
  const name = iconNameFor(themeId, defaultTheme);
  try {
    if ((mod.getAppIconName?.() ?? null) === name) return true;
    await mod.setAlternateAppIcon(name);
    return true;
  } catch {
    return false;
  }
}
